340	// The invoices raised against a project: what they add up to, a form to raise another, and a drill-in
341	// to each invoice's line items and payments. Owns its own invoice state, scoped to the one project.
342	// Whenever the invoices change (a new one raised, a status moved, a line item edited) the owner is
343	// told so figures derived from them — the budget's invoiced/remaining — can be refreshed.
344	function ProjectInvoices({
345	  projectId,
346	  onInvoicesChanged,
347	}: {
348	  projectId: number;
349	  onInvoicesChanged: () => void;
350	}) {
351	  const [invoices, setInvoices] = useState<Invoice[]>([]);
352	  const [amount, setAmount] = useState('');
353	  const [amountError, setAmountError] = useState('');
354	  const [sortByDue, setSortByDue] = useState(false);
355	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
356	
357	  async function load() {
358	    const res = await fetch(`/api/invoices?projectId=${projectId}`);
359	    setInvoices(await res.json());
360	    onInvoicesChanged();
361	  }
362	
363	  useEffect(() => {
364	    void load();
365	  }, [projectId]);
366	
367	  async function submit(e: React.FormEvent) {
368	    e.preventDefault();
369	    const value = Number(amount);
370	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
371	      setAmountError('Amount must be more than zero');
372	      return;
373	    }
374	    setAmountError('');
375	    await fetch('/api/invoices', {
376	      method: 'POST',
377	      headers: { 'Content-Type': 'application/json' },
378	      body: JSON.stringify({ projectId, amount: value }),
379	    });
380	    setAmount('');
381	    await load();
382	  }
383	
384	  // A lifecycle move (send, mark paid, …) is a POST to the matching action route followed by a reload;
385	  // routing them through one place means a new action is one more call site, not new plumbing.
386	  async function transition(id: number, action: 'send' | 'pay') {
387	    await fetch(`/api/invoices/${id}/${action}`, { method: 'POST' });
388	    await load();
389	  }
390	
391	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
392	  const shownInvoices = sortByDue
393	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
394	    : invoices;
395	
396	  return (
397	    <>
398	      <form data-testid="invoice-form" onSubmit={submit}>
399	        <input
400	          data-testid="invoice-form-amount"
401	          placeholder="Amount"
402	          value={amount}
403	          onChange={(e) => setAmount(e.target.value)}
404	        />
405	        <button data-testid="invoice-form-submit" type="submit">
406	          Add invoice
407	        </button>
408	        {amountError && (
409	          <p data-testid="invoice-form-amount-error" role="alert">
410	            {amountError}
411	          </p>
412	        )}
413	      </form>
414	
415	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
416	        Sort by due date
417	      </button>
418	
419	      {openInvoiceId === null ? (
420	        <>
421	          <table data-testid="project-invoices-table">
422	            <tbody>
423	              {shownInvoices.map((inv) => (
424	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
425	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
426	                  <td data-testid="invoice-due-amount">{money(inv.amountDue)}</td>
427	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
428	                  <td data-testid="invoice-due">{inv.dueDate}</td>
429	                  <td data-testid="invoice-status">{inv.status}</td>
430	                  <td>
431	                    <InvoiceActions
432	                      invoice={inv}
433	                      onOpen={() => setOpenInvoiceId(inv.id)}
434	                      onSend={() => transition(inv.id, 'send')}
435	                      onPay={() => transition(inv.id, 'pay')}
436	                    />
437	                  </td>
438	                </tr>
439	              ))}
440	            </tbody>
441	          </table>
442	
443	          <p data-testid="project-invoices-total">{money(total)}</p>
444	        </>
445	      ) : (
446	        <InvoiceDetail
447	          invoiceId={openInvoiceId}
448	          onChange={load}
449	          onClose={() => setOpenInvoiceId(null)}
450	        />
451	      )}
452	    </>
453	  );
454	}
