520	    setTags(mine);
521	    setAllTags(all);
522	  }
523	
524	  useEffect(() => {
525	    void loadBudget();
526	    void loadTasks();
527	    void loadTags();
528	    void loadNotes();
529	  }, [project.id]);
530	
531	  async function toggleTask(id: number) {
532	    await fetch(`/api/tasks/${id}/toggle`, { method: 'POST' });
533	    await loadTasks();
534	  }
535	
536	  async function addTag(e: React.FormEvent) {
537	    e.preventDefault();
538	    if (!tagToAdd) {
539	      return;
540	    }
541	    await fetch(`/api/projects/${project.id}/tags`, {
542	      method: 'POST',
543	      headers: { 'Content-Type': 'application/json' },
544	      body: JSON.stringify({ tagId: Number(tagToAdd) }),
545	    });
546	    setTagToAdd('');
547	    await loadTags();
