674	function ProjectsPage() {
675	  const [projects, setProjects] = useState<Project[]>([]);
676	  const [clients, setClients] = useState<Client[]>([]);
677	  const [tags, setTags] = useState<Tag[]>([]);
678	  const [tagLinks, setTagLinks] = useState<ProjectTagLink[]>([]);
679	  const [tagFilter, setTagFilter] = useState('');
680	  const [statusFilter, setStatusFilter] = useState('');
