682	  const [clientId, setClientId] = useState('');
683	  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');
684	  const [openId, setOpenId] = useState<number | null>(null);
685	  // Archived projects are tucked away (retained, not deleted) and hidden by default; this toggle
686	  // reveals them again.
687	  const [showArchived, setShowArchived] = useState(false);
688	
689	  async function loadProjects() {
690	    const res = await fetch('/api/projects');
691	    setProjects(await res.json());
692	  }
693	
694	  async function loadClients() {
695	    const res = await fetch('/api/clients');
696	    setClients(await res.json());
697	  }
698	
699	  async function loadTags() {
700	    const [all, links] = await Promise.all([
701	      fetch('/api/tags').then((r) => r.json()),
702	      fetch('/api/project-tags').then((r) => r.json()),
703	    ]);
704	    setTags(all);
705	    setTagLinks(links);
706	  }
707	
708	  useEffect(() => {
709	    void loadProjects();
710	    void loadClients();
711	    void loadTags();
712	  }, []);
713	
714	  async function submit(e: React.FormEvent) {
715	    e.preventDefault();
716	    if (!name.trim() || !clientId) {
717	      return;
718	    }
719	    await fetch('/api/projects', {
720	      method: 'POST',
721	      headers: { 'Content-Type': 'application/json' },
722	      body: JSON.stringify({ name, clientId: Number(clientId), status }),
723	    });
724	    setName('');
725	    setClientId('');
726	    setStatus('ACTIVE');
727	    await loadProjects();
728	  }
729	
730	  async function remove(id: number) {
731	    await fetch(`/api/projects/${id}/delete`, { method: 'POST' });
732	    if (openId === id) {
733	      setOpenId(null);
734	    }
735	    await loadProjects();
736	  }
737	
738	  async function archive(id: number) {
739	    await fetch(`/api/projects/${id}/archive`, { method: 'POST' });
740	    if (openId === id) {
741	      setOpenId(null);
742	    }
743	    await loadProjects();
744	  }
745	
746	  const open = projects.find((p) => p.id === openId) ?? null;
747	  const byArchived = showArchived ? projects : projects.filter((p) => !p.archived);
748	  const filterTagId = tagFilter ? Number(tagFilter) : null;
749	  const byTag =
750	    filterTagId === null
751	      ? byArchived
752	      : byArchived.filter((p) =>
753	          tagLinks.some((l) => l.projectId === p.id && l.tagId === filterTagId),
754	        );
755	  const visible = statusFilter ? byTag.filter((p) => p.status === statusFilter) : byTag;
756	
757	  return (
758	    <section data-testid="projects">
