763	          value={name}
764	          onChange={(e) => setName(e.target.value)}
765	        />
766	        <select
767	          data-testid="project-form-client"
768	          value={clientId}
769	          onChange={(e) => setClientId(e.target.value)}
770	        >
771	          <option value="">Select a client</option>
772	          {clients.map((c) => (
773	            <option key={c.id} value={String(c.id)}>
774	              {c.name}
