779	          data-testid="project-form-status"
780	          value={status}
781	          onChange={(e) => setStatus(e.target.value as ProjectStatus)}
782	        >
783	          <option value="ACTIVE">Active</option>
784	          <option value="ON_HOLD">On hold</option>
785	          <option value="FINISHED">Finished</option>
786	        </select>
787	        <button data-testid="project-form-submit" type="submit">
788	          Add project
789	        </button>
790	      </form>
791	
792	      <button
793	        data-testid="projects-show-archived"
794	        type="button"
795	        onClick={() => setShowArchived((v) => !v)}
796	      >
797	        {showArchived ? 'Hide archived' : 'Show archived'}
798	      </button>
799	
800	      <select
801	        data-testid="project-tag-filter"
802	        value={tagFilter}
803	        onChange={(e) => setTagFilter(e.target.value)}
804	      >
805	        <option value="">All labels</option>
806	        {tags.map((t) => (
807	          <option key={t.id} value={String(t.id)}>
808	            {t.name}
809	          </option>
810	        ))}
811	      </select>
812	
813	      <select
814	        data-testid="project-status-filter"
815	        value={statusFilter}
816	        onChange={(e) => setStatusFilter(e.target.value)}
