822	      </select>
823	
824	      {projects.length === 0 ? (
825	        <p data-testid="projects-empty">No projects yet.</p>
826	      ) : (
827	        <table data-testid="projects-table">
828	          <tbody>
829	            {visible.map((p) => (
830	              <tr key={p.id} data-testid={`project-row-${p.id}`}>
831	                <td data-testid="project-name">{p.name}</td>
832	                <td data-testid="project-client">{p.clientName}</td>
833	                <td data-testid="project-status">{p.status}</td>
834	                <td>
835	                  <button data-testid={`project-open-${p.id}`} onClick={() => setOpenId(p.id)}>
836	                    Open
837	                  </button>
