842	                    Delete
843	                  </button>
844	                </td>
845	              </tr>
846	            ))}
847	          </tbody>
848	        </table>
849	      )}
850	
851	      {open && <ProjectDetail key={open.id} project={open} />}
852	    </section>
853	  );
854	}
