1	package net.officefloor.hq.app;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Map;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 *
19	 * <p>{@link #seed} is a plain sequence of one {@code seed*} method per entity. Teaching a new entity
20	 * to the harness is therefore additive: add its {@code seed*} method, call it from {@link #seed},
21	 * and add its {@code TRUNCATE} to {@link #reset} — no existing entity's code is touched.
22	 */
23	@Profile("harness")
24	@RestController
25	@RequestMapping("/__test__")
26	public class TestSupportController {
27	
28	    private final Audit audit;
29	    private final JdbcTemplate jdbc;
30	
31	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
32	        this.audit = audit;
33	        this.jdbc = jdbc;
34	    }
35	
36	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
37	    @PostMapping("/reset")
38	    public void reset() {
39	        audit.clear();
40	        // Referential integrity is dropped for the duration so the tables can be truncated (and
41	        // their identity counters restarted) regardless of FK order (e.g. projects -> clients).
42	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
43	        for (String table : List.of("dashboard_clock", "notes", "project_tags", "tags", "tasks",
44	                "payments", "line_items", "invoices", "contacts", "projects", "clients")) {
45	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
46	        }
47	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
48	    }
49	
50	    /** Insert the fixture a spec needs; each entity is seeded by its own {@code seed*} method. */
51	    @PostMapping("/seed")
52	    public void seed(@RequestBody Map<String, Object> fixture) {
53	        seedClients(fixture);
54	        seedProjects(fixture);
55	        seedContacts(fixture);
56	        seedInvoices(fixture);
57	        seedPayments(fixture);
58	        seedTasks(fixture);
59	        seedTags(fixture);
60	        seedNotes(fixture);
61	        seedProjectTags(fixture);
62	        seedClock(fixture);
63	    }
64	
65	    private void seedClock(Map<String, Object> fixture) {
66	        // The dashboard's fixed "as of" reference date (top-level asOf), if the fixture supplies one.
67	        Object asOf = fixture.get("asOf");
68	        if (asOf != null) {
69	            jdbc.update("INSERT INTO dashboard_clock (id, as_of) VALUES (1, ?)", asOf.toString());
70	        }
71	    }
72	
73	    private void seedClients(Map<String, Object> fixture) {
74	        for (Map<String, Object> c : rows(fixture, "clients")) {
75	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
76	                    id(c, "id"), c.get("name"), c.get("email"));
77	        }
78	    }
79	
80	    private void seedProjects(Map<String, Object> fixture) {
81	        for (Map<String, Object> p : rows(fixture, "projects")) {
82	            // status defaults to ACTIVE so a fixture that omits it gets an active project; archived
83	            // defaults to FALSE (the table default) unless the fixture pins it.
84	            new Insert("projects")
85	                    .set("id", id(p, "id"))
86	                    .set("name", p.get("name"))
87	                    .set("client_id", id(p, "clientId"))
88	                    .set("status", p.get("status") == null ? "ACTIVE" : p.get("status").toString())
89	                    .setIfPresent("archived", p.get("archived"))
90	                    .setIfPresent("budget", asDouble(p.get("budget")))
91	                    .run();
92	        }
93	    }
94	
95	    private void seedContacts(Map<String, Object> fixture) {
96	        for (Map<String, Object> ct : rows(fixture, "contacts")) {
97	            jdbc.update(
98	                    "INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
99	                    id(ct, "id"), id(ct, "clientId"), ct.get("name"), ct.get("email"),
100	                    ct.get("role"));
101	        }
102	    }
103	
104	    private void seedInvoices(Map<String, Object> fixture) {
105	        for (Map<String, Object> in : rows(fixture, "invoices")) {
106	            // Insert only the columns the fixture supplies, so the table's own defaults apply when a
107	            // fixture omits them (a plain null would trip the NOT NULL columns). status defaults to
108	            // DRAFT and amount defaults to 0 — an invoice's amount is derived from its line items,
109	            // so fixtures list lineItems rather than a single typed amount.
110	            new Insert("invoices")
111	                    .set("id", id(in, "id"))
112	                    .set("project_id", id(in, "projectId"))
113	                    .set("status", in.get("status") == null ? "DRAFT" : in.get("status").toString())
114	                    .setIfPresent("amount", asDouble(in.get("amount")))
115	                    .setIfPresent("issued_date", asText(in.get("issuedDate")))
116	                    .setIfPresent("due_date", asText(in.get("dueDate")))
117	                    .run();
118	            seedLineItems(in);
119	        }
120	    }
121	
122	    private void seedLineItems(Map<String, Object> invoice) {
123	        long invoiceId = id(invoice, "id");
124	        for (Map<String, Object> li : rows(invoice, "lineItems")) {
125	            jdbc.update(
126	                    "INSERT INTO line_items (id, invoice_id, description, qty, unit_price)"
127	                            + " VALUES (?, ?, ?, ?, ?)",
128	                    id(li, "id"), invoiceId, li.get("description"),
129	                    ((Number) li.get("qty")).intValue(),
130	                    ((Number) li.get("unitPrice")).doubleValue());
131	        }
132	    }
133	
134	    private void seedPayments(Map<String, Object> fixture) {
135	        List<Map<String, Object>> payments = rows(fixture, "payments");
136	        for (Map<String, Object> p : payments) {
137	            jdbc.update(
138	                    "INSERT INTO payments (id, invoice_id, amount, paid_date) VALUES (?, ?, ?, ?)",
139	                    id(p, "id"), id(p, "invoiceId"), asDouble(p.get("amount")),
140	                    asText(p.get("date")));
141	        }
142	        if (!payments.isEmpty()) {
143	            // Seeding explicit ids does not advance H2's identity counter, so bump it past the
144	            // seeded rows or the app's next generated payment id would collide with a fixture id.
145	            Long next = jdbc.queryForObject("SELECT MAX(id) + 1 FROM payments", Long.class);
146	            jdbc.execute("ALTER TABLE payments ALTER COLUMN id RESTART WITH " + next);
147	        }
148	    }
149	
150	    private void seedTasks(Map<String, Object> fixture) {
151	        for (Map<String, Object> t : rows(fixture, "tasks")) {
152	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
153	                    id(t, "id"), id(t, "projectId"), t.get("title"),
154	                    Boolean.TRUE.equals(t.get("done")));
155	        }
156	    }
157	
158	    private void seedTags(Map<String, Object> fixture) {
159	        for (Map<String, Object> tg : rows(fixture, "tags")) {
160	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)", id(tg, "id"), tg.get("name"));
161	        }
162	    }
163	
164	    private void seedNotes(Map<String, Object> fixture) {
165	        List<Map<String, Object>> notes = rows(fixture, "notes");
166	        for (Map<String, Object> n : notes) {
167	            jdbc.update(
168	                    "INSERT INTO notes (id, target_type, target_id, text, created_at)"
169	                            + " VALUES (?, ?, ?, ?, ?)",
170	                    id(n, "id"), n.get("targetType"), id(n, "targetId"), n.get("text"),
171	                    n.get("at").toString());
172	        }
173	        if (!notes.isEmpty()) {
174	            // Seeding explicit ids does not advance H2's identity counter, so bump it past the
175	            // seeded rows or the app's next generated note id would collide with a fixture id.
176	            Long next = jdbc.queryForObject("SELECT MAX(id) + 1 FROM notes", Long.class);
177	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + next);
178	        }
179	    }
180	
181	    private void seedProjectTags(Map<String, Object> fixture) {
182	        for (Map<String, Object> pt : rows(fixture, "projectTags")) {
183	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
184	                    id(pt, "projectId"), id(pt, "tagId"));
185	        }
186	    }
187	
188	    /** The list of fixture rows under {@code key}, or an empty list when the fixture omits it. */
189	    @SuppressWarnings("unchecked")
190	    private static List<Map<String, Object>> rows(Map<String, Object> fixture, String key) {
191	        return (List<Map<String, Object>>) fixture.getOrDefault(key, List.of());
192	    }
193	
194	    /** A fixture id column: JSON numbers arrive as {@link Number}, the tables use {@code BIGINT}. */
195	    private static long id(Map<String, Object> row, String key) {
196	        return ((Number) row.get(key)).longValue();
197	    }
198	
199	    private static Double asDouble(Object value) {
200	        return value == null ? null : ((Number) value).doubleValue();
201	    }
202	
203	    private static String asText(Object value) {
204	        return value == null ? null : value.toString();
205	    }
206	
207	    /**
208	     * Builds an {@code INSERT} whose column set is decided per row, so a fixture can omit a column
209	     * and let the table's own default apply (a bare null would trip a NOT NULL column). Required
210	     * columns are added with {@link #set}; optional ones with {@link #setIfPresent}.
211	     */
212	    private final class Insert {
213	        private final String table;
214	        private final StringBuilder cols = new StringBuilder();
215	        private final StringBuilder marks = new StringBuilder();
216	        private final List<Object> args = new ArrayList<>();
217	
218	        Insert(String table) {
219	            this.table = table;
220	        }
221	
222	        Insert set(String column, Object value) {
223	            if (cols.length() > 0) {
224	                cols.append(", ");
225	                marks.append(", ");
226	            }
227	            cols.append(column);
228	            marks.append("?");
229	            args.add(value);
